/**
 * AskFor (W1-D): the Record's per-step answer card, extracted so another shell can render it.
 *
 * The reference is what the Record rendered BEFORE the extraction: for every question key, the
 * question block is stored as HTML in __askfor_before__/, captured from the Record on the base
 * commit (bf289d1c) and never regenerated by this test. The Record must still render exactly
 * that, and AskFor, given only the project and the step key, must render the same card.
 */
import { readFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { fireEvent, render, waitFor, within } from "@testing-library/react";
import { api, RefusalError } from "../../api/client";
import { keys } from "../../api/queries";
import {
  QUESTION_KEYS,
  type InterviewStep,
  type QuestionKey,
  type TeachingEntry,
} from "../../api/m1-types";
import type { Decision, ProjectView, Refusal } from "../../api/schema";
import { artifactAt, expandView, viewsOf, type M3Fixture } from "../../mocks/m3";
import { StageFocusProvider } from "../../state/focus";
import { AskFor } from "./AskFor";
import { Record } from "./Record";

const HERE = dirname(fileURLToPath(import.meta.url));
const BEFORE = resolve(HERE, "__askfor_before__");
const PID = "m3-test";

const FIXTURES = import.meta.glob<M3Fixture>("../../mocks/fixtures/m3-*.json", {
  eager: true,
  import: "default",
});
const SHARED = Object.entries(FIXTURES).find(([p]) =>
  p.endsWith("m3-shared.json"),
)![1] as unknown as {
  teaching: TeachingEntry[];
};
const JOURNEYS = Object.entries(FIXTURES)
  .filter(([p]) => !p.endsWith("m3-shared.json"))
  .map(([p, f]) => ({ name: /m3-(.+)\.json$/.exec(p)![1]!, f, views: viewsOf(f) }));

/** A view where `key` is the open question: as captured, else its latest captured state forced open. */
function openViewFor(key: QuestionKey): { view: ProjectView; f: M3Fixture } {
  for (const { f, views } of JOURNEYS) {
    const i = views.findIndex((v) => v.interview.some((s) => s.key === key && s.status === "open"));
    if (i !== -1) return { view: expandView(f, views[i]!, PID, "2026-10-05T00:00:00Z"), f };
  }
  for (const { f, views } of JOURNEYS) {
    for (let i = views.length - 1; i >= 0; i--) {
      const v = views[i]!;
      const step = v.interview.find((s) => s.key === key);
      if (!step || step.status === "not_applicable" || step.status === "waiting") continue;
      const interview: InterviewStep[] = v.interview.map((s) =>
        s.key === key
          ? { ...s, status: "open", waiting_on: [] }
          : s.status === "open" || s.status === "waiting"
            ? { ...s, status: "waiting", waiting_on: [key] }
            : s,
      );
      return { view: expandView(f, { ...v, interview }, PID, "2026-10-05T00:00:00Z"), f };
    }
  }
  throw new Error(`no captured journey reaches ${key}`);
}

function client(view: ProjectView, f: M3Fixture) {
  const qc = new QueryClient({
    defaultOptions: { queries: { retry: false, staleTime: Infinity } },
  });
  qc.setQueryData(keys.teaching(), SHARED.teaching);
  // The roles card asks for the project's goal (finding 3c); the server words every card alike
  // under every goal but prediction (core/teaching/content.py `entries_now`), so the captured words
  // with no goal named are that goal's words too.
  const purpose = view.state.purpose;
  if (purpose && purpose !== "prediction") qc.setQueryData(keys.teaching(purpose), SHARED.teaching);
  qc.setQueryData(keys.view(PID), view);
  const columns = f.endpoints.columns;
  if (columns?.status === 200) qc.setQueryData(keys.columns(PID), columns.body);
  for (const [stage, status] of Object.entries(view.stages)) {
    if (!status || status.status === "idle" || status.status === "blocked") continue;
    qc.setQueryData(keys.stage(PID, stage), {
      stage,
      key: status.key,
      fresh: status.status === "fresh",
      status: status.status,
      artifact: artifactAt(f, stage, status.key),
    });
  }
  return qc;
}

/** Question-block HTML with React's generated ids (`_r_3p_`) numbered in order of appearance, so
 *  the comparison does not depend on how many components rendered before it. */
function normalize(html: string): string {
  const ids = new Map<string, string>();
  const tag = (id: string) => {
    if (!ids.has(id)) ids.set(id, `_id${ids.size}_`);
    return ids.get(id)!;
  };
  return html
    .replace(/_r_[0-9a-z]+_/g, tag)
    .replace(/\s+style="[^"]*"/g, "")
    .trim();
}

function blockOf(container: HTMLElement, key: QuestionKey): Element {
  const block = container.querySelector(`[data-testid="question-${key}"]`);
  if (!block) throw new Error(`no question block for ${key}`);
  return block;
}

/** The keys the Record's ask(key) answers: every key but the seal's opening, which is a step of its own. */
const ASKED = QUESTION_KEYS.filter((k) => k !== "open_seal");

const before = (key: string) => normalize(readFileSync(resolve(BEFORE, `${key}.html`), "utf-8"));

describe("the Record renders each question exactly as it did before the extraction", () => {
  for (const key of ASKED) {
    it(key, () => {
      const { view, f } = openViewFor(key);
      const { container } = render(
        <QueryClientProvider client={client(view, f)}>
          <StageFocusProvider>
            <Record pid={PID} view={view} />
          </StageFocusProvider>
        </QueryClientProvider>,
      );
      expect(normalize(blockOf(container, key).outerHTML)).toBe(before(key));
    });
  }
});

describe("AskFor renders the same card for a step key", () => {
  for (const key of ASKED) {
    it(key, () => {
      const { view, f } = openViewFor(key);
      const { container } = render(
        <QueryClientProvider client={client(view, f)}>
          <StageFocusProvider>
            <AskFor pid={PID} view={view} stepKey={key} />
          </StageFocusProvider>
        </QueryClientProvider>,
      );
      expect(normalize(blockOf(container, key).outerHTML)).toBe(before(key));
    });
  }
});

/* The question blocks that carry a coach line or the ledger's ask card, each as the base Record
 * rendered it for one captured view (journey, snapshot index): coach~<journey>~<i>.html and
 * ask~<journey>~<i>.html in __askfor_before__/, captured from bf289d1c's Record. */
const CAPTURED: { kind: "coach" | "ask"; journey: string; i: number }[] = [
  { kind: "coach", journey: "nhanes-inference", i: 4 },
  { kind: "coach", journey: "nhanes-inference", i: 5 },
  { kind: "coach", journey: "nhanes-prediction", i: 5 },
  { kind: "coach", journey: "nhanes-prediction", i: 6 },
  { kind: "coach", journey: "survey-design", i: 6 },
  { kind: "ask", journey: "clinical", i: 14 },
  { kind: "ask", journey: "dietary-recalls", i: 8 },
  { kind: "ask", journey: "survey-design", i: 4 },
];

function capturedView(journey: string, i: number) {
  const j = JOURNEYS.find((x) => x.name === journey)!;
  const view = expandView(j.f, j.views[i]!, PID, "2026-10-05T00:00:00Z");
  const key = view.interview.find((s) => s.status === "open")!.key;
  return { view, f: j.f, key };
}

describe("the coach line and the ledger's ask card render as before, in the Record and in AskFor", () => {
  for (const { kind, journey, i } of CAPTURED) {
    const file = `${kind}~${journey}~${i}`;
    const marker = kind === "coach" ? 'data-testid="coach-' : 'data-testid="ask-card"';
    it(`${file}: the Record`, () => {
      const html = before(file);
      expect(html).toContain(marker); // the reference really holds what this case guards
      const { view, f, key } = capturedView(journey, i);
      const { container } = render(
        <QueryClientProvider client={client(view, f)}>
          <StageFocusProvider>
            <Record pid={PID} view={view} />
          </StageFocusProvider>
        </QueryClientProvider>,
      );
      expect(normalize(blockOf(container, key).outerHTML)).toBe(html);
    });
    it(`${file}: AskFor`, () => {
      const { view, f, key } = capturedView(journey, i);
      const { container } = render(
        <QueryClientProvider client={client(view, f)}>
          <StageFocusProvider>
            <AskFor pid={PID} view={view} stepKey={key} />
          </StageFocusProvider>
        </QueryClientProvider>,
      );
      expect(normalize(blockOf(container, key).outerHTML)).toBe(before(file));
    });
  }
});

describe("the Record holds every stage the cards read while it is mounted, with no card open", () => {
  /** The stages and the column summaries the base Record subscribed to for the cards' sake. */
  const CARD_STAGES = [
    "structure",
    "profile",
    "roles",
    "proposals",
    "shelf",
    "causal_design",
    "time_varying",
    "forms",
  ] as const;

  it("observes each started stage and the column summaries at the seal's opening", () => {
    const j = JOURNEYS.find((x) => x.name === "nhanes-prediction")!;
    const i = j.views.findIndex((v) =>
      v.interview.some((s) => s.key === "open_seal" && s.status === "open"),
    );
    expect(i).toBeGreaterThan(-1);
    const view = expandView(j.f, j.views[i]!, PID, "2026-10-05T00:00:00Z");
    const qc = client(view, j.f);
    const { container } = render(
      <QueryClientProvider client={qc}>
        <StageFocusProvider>
          <Record pid={PID} view={view} />
        </StageFocusProvider>
      </QueryClientProvider>,
    );
    // No question card is mounted: only the Record can hold these.
    expect(container.querySelector('[data-block="question"]')).toBeNull();
    const observers = (key: readonly unknown[]) =>
      qc.getQueryCache().find({ queryKey: key, exact: true })?.getObserversCount() ?? 0;
    const started = CARD_STAGES.filter((st) => {
      const status = view.stages[st]?.status;
      return status !== undefined && status !== "idle" && status !== "blocked";
    });
    // The journey has run past the questions: the five that every Predict project computes.
    expect(started).toEqual(
      expect.arrayContaining(["structure", "profile", "roles", "proposals", "shelf"]),
    );
    for (const st of started) expect(observers(keys.stage(PID, st)), st).toBeGreaterThanOrEqual(1);
    expect(view.stages.ingest?.status).toBe("fresh");
    expect(observers(keys.columns(PID)), "columns").toBeGreaterThanOrEqual(1);
  });
});

/**
 * W1-R finding 3c (R2 P3a, the shell's side): the roles card asks for the project's goal, since the
 * server words it by goal (GET /teaching?purpose=; core/teaching/content.py ROLES_UNDER_PREDICT),
 * and under prediction its own words say predictors; under any other goal both stand as before.
 * The Predict entry is the captured one with its one-liner and exposure option worded as
 * content.py's ROLES_UNDER_PREDICT and `_PREDICT_OPTIONS` word them, so which entry the card read
 * is seen on the card and its role menu.
 */
describe("the roles card, by the project's goal (finding 3c)", () => {
  const { view: base, f } = openViewFor("roles");
  const PREDICT = SHARED.teaching.map((e) =>
    e.key === "roles"
      ? {
          ...e,
          one_liner: "Only predictors, covariates and the energy column enter the models; every other role stays out of them.",
          options: e.options.map((o) => (o.value === "exposure" ? { ...o, label: "Predictor" } : o)),
        }
      : e,
  );
  const withGoal = (purpose: string) => ({ ...base, state: { ...base.state, purpose } }) as ProjectView;
  /** The roles card, with the words for each goal seeded where the hook would read them. */
  function renderRoles(view: ProjectView) {
    const qc = client(view, f);
    qc.setQueryData(keys.teaching("prediction"), PREDICT);
    const out = render(
      <QueryClientProvider client={qc}>
        <StageFocusProvider>
          <AskFor pid={PID} view={view} stepKey="roles" />
        </StageFocusProvider>
      </QueryClientProvider>,
    );
    return within(out.container);
  }
  const roles = (view: ProjectView) => {
    const art = artifactAt(f, "roles", view.stages.roles!.key) as { columns: { column: string; proposed: string }[] };
    const role = (c: { column: string; proposed: string }) => (view.state.roles as Record<string, string> | null)?.[c.column] ?? c.proposed;
    const exposures = art.columns.filter((c) => role(c) === "exposure");
    const predictors = art.columns.filter((c) => ["exposure", "energy", "covariate"].includes(role(c)));
    return { exposures, predictors };
  };

  it("reads the words for prediction under Predict, and says predictors", () => {
    const view = withGoal("prediction");
    const { exposures, predictors } = roles(view);
    expect(exposures.length).toBeGreaterThan(1);
    const card = renderRoles(view);
    const block = card.getByTestId("question-roles");
    expect(block.textContent).toContain(`${predictors.length} columns enter the models: ${exposures.length} predictors`);
    expect(block.textContent).not.toMatch(/exposures?\b/);
    expect(block.querySelector('[data-role="exposure"]')!.textContent).toContain("Predictors");
    fireEvent.click(card.getByTestId(`role-chip-${exposures[0]!.column}`));
    expect(card.getByTestId("role-exposure").textContent).toContain("Predictor");
  });

  it("reads the words with no goal named under any other goal, as before", () => {
    const view = withGoal("inference");
    const { exposures, predictors } = roles(view);
    const card = renderRoles(view);
    const block = card.getByTestId("question-roles");
    expect(block.textContent).toContain(`${predictors.length} columns become predictors: ${exposures.length} exposures`);
    fireEvent.click(card.getByTestId(`role-chip-${exposures[0]!.column}`));
    const served = SHARED.teaching.find((e) => e.key === "roles")!.options.find((o) => o.value === "exposure")!.label;
    expect(card.getByTestId("role-exposure").textContent).toContain(served);
    expect(card.getByTestId("role-exposure").textContent).not.toContain("Predictor");
  });
});

describe("AskFor on its own answers a press that did not record at its control", () => {
  const { view, f, key } = capturedView("survey-design", 4);
  const exitDecision = { kind: "set_purpose", purpose: "inference" } as unknown as Decision;
  const refusal: Refusal = {
    error: {
      code: "conflict",
      message: "The survey design needs its weight column first.",
      exits: [{ label: "Set the purpose", decision: exitDecision }],
    },
  };
  const renderPlain = () =>
    render(
      <QueryClientProvider client={client(view, f)}>
        <StageFocusProvider>
          <AskFor pid={PID} view={view} stepKey={key} />
        </StageFocusProvider>
      </QueryClientProvider>,
    );

  it("shows the server's refusal at the ask card's line, and an exit records its decision", async () => {
    const decide = vi.spyOn(api, "decide").mockRejectedValue(new RefusalError(refusal));
    const { container } = renderPlain();
    const card = within(container.querySelector<HTMLElement>('[data-testid="ask-card"]')!);
    fireEvent.click(card.getAllByTestId("ask-confirm")[0]!);
    const note = await card.findByTestId("refusal");
    expect(note.textContent).toContain("The survey design needs its weight column first.");
    fireEvent.click(within(note).getByTestId("refusal-exit"));
    await waitFor(() => expect(decide).toHaveBeenCalledTimes(2));
    expect(decide.mock.calls[1]![1]).toEqual(exitDecision);
    decide.mockRestore();
  });

  it("says the server did not record it when the request fails", async () => {
    const decide = vi.spyOn(api, "decide").mockRejectedValue(new Error("connection reset"));
    const { container } = renderPlain();
    const card = within(container.querySelector<HTMLElement>('[data-testid="ask-card"]')!);
    fireEvent.click(card.getAllByTestId("ask-confirm")[0]!);
    const note = await card.findByTestId("failure");
    expect(note.textContent).toContain("connection reset");
    fireEvent.click(within(note).getByRole("button", { name: "Understood" }));
    expect(card.queryByTestId("failure")).toBeNull();
    decide.mockRestore();
  });
});
